const $ = (id) => document.getElementById(id);
const screens = ['menu','room','auth','saves','play'];
let mode = 'login', currentName = null, afterLogin = 'room', saveRows = [], characterName = null, introTimer = null;
function show(screen){screens.forEach(id=>$(id).hidden=id!==screen);window.scrollTo(0,0);}
function updateAccount(name){currentName=name;$('player').textContent=name?`调查员 · ${name}`:'身份未确认';$('clue-title').textContent=name?'身份已确认':'登录游戏';$('clue-note').textContent=name?'查看你的调查身份':'点击查验 · 建立身份';$('stamp').hidden=!name;$('case-note').textContent=name?`欢迎回来，${name}。你的调查身份已记录。`:'第一条线索：确认你的身份。';$('logout').hidden=!name;$('save-note').textContent=name?'读取中…':'登录后读取存档';saveRows=[];characterName=null;renderSaves();if(name){restoreProfile();refreshSaves(false);}}
async function request(path,body){const response=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,credentials:'same-origin'});const data=await response.json();if(!response.ok)throw new Error(data.error||'暂时无法连接，请稍后重试。');return data;}
function setMode(next){mode=next;$('auth-title').textContent=mode==='login'?'登录游戏':'建立调查身份';$('auth-sub').textContent=mode==='login'?'每一道红线，都从一个名字开始。':'留下你的名字。记住你的密码。';$('submit').textContent=mode==='login'?'确认身份':'创建账号';$('switch').textContent=mode==='login'?'没有账号？创建一个':'已有账号？返回登录';$('password').autocomplete=mode==='login'?'current-password':'new-password';$('form-message').textContent='';}
$('start').addEventListener('click',()=>{startMusic();if(location.hostname.endsWith('chatgpt.site')){location.href='https://qize-star-game.onrender.com/?scene=board';return;}show('room');});
$('menu-back').addEventListener('click',()=>show('menu'));
$('clue').addEventListener('click',()=>{if(currentName){$('case-note').textContent=`调查员 ${currentName}，身份线索已完成。`;return;}afterLogin='room';setMode('login');show('auth');$('name').focus({preventScroll:true});});
$('auth-back').addEventListener('click',()=>show('room'));
$('switch').addEventListener('click',()=>setMode(mode==='login'?'register':'login'));
$('auth-form').addEventListener('submit',async(event)=>{event.preventDefault();$('submit').disabled=true;$('form-message').textContent='正在查验身份…';try{const data=await request(mode,{name:$('name').value.trim(),password:$('password').value});$('password').value='';updateAccount(data.name);show(afterLogin);if(afterLogin==='play')beginStory();if(afterLogin==='saves')await refreshSaves(true);}catch(error){$('form-message').textContent=error.message;}finally{$('submit').disabled=false;}});
$('logout').addEventListener('click',async()=>{try{await request('logout',{});updateAccount(null);}catch(error){$('case-note').textContent=error.message;}});
let musicEnabled=true;
const bgm=$('bgm');bgm.src=window.QIZE_BGM;
function startMusic(){if(!musicEnabled||!bgm.paused)return;bgm.play().catch(()=>{});}
document.addEventListener('click',startMusic);document.addEventListener('touchend',startMusic,{passive:true});document.addEventListener('keydown',startMusic);startMusic();
let touchX=0,touchY=0;
document.addEventListener('touchstart',event=>{if(event.touches.length!==1)return;touchX=event.touches[0].clientX;touchY=event.touches[0].clientY;startMusic();},{passive:true});
document.addEventListener('touchmove',event=>{if(event.touches.length!==1)return;const dx=event.touches[0].clientX-touchX,dy=event.touches[0].clientY-touchY;const page=document.scrollingElement;if(Math.abs(dx)>Math.abs(dy)||(page.scrollTop<=0&&dy>0)||(page.scrollTop+page.clientHeight>=page.scrollHeight-1&&dy<0)){if(event.cancelable)event.preventDefault();}},{passive:false});
if(new URLSearchParams(location.search).get('scene')==='board')show('room');
if(!location.hostname.endsWith('chatgpt.site'))request('session').then(data=>updateAccount(data.name)).catch(()=>{});

function renderSaves(){const list=$('save-list');list.replaceChildren();for(let slot=1;slot<=3;slot++){const row=saveRows.find(x=>x.slot===slot);const box=document.createElement('article');box.className='save-slot';const title=document.createElement('h2');title.textContent='存档 '+String(slot).padStart(2,'0');const text=document.createElement('p');text.textContent=row?((row.state.character_name||characterName||'未命名')+' · 第一章'+(row.state.scene==='play'?' · 初次相遇':' · 身份线索已确认')):'暂无存档';const time=document.createElement('p');time.textContent=row?'保存于 '+new Date(row.updated_at).toLocaleString():'可在这里保存当前进度';const actions=document.createElement('div');actions.className='slot-buttons';const write=document.createElement('button');write.type='button';write.textContent=row?'更新存档':'保存当前进度';write.addEventListener('click',()=>saveSlot(slot));const read=document.createElement('button');read.type='button';read.textContent='读取存档';read.disabled=!row;read.addEventListener('click',()=>{if(!['board','play'].includes(row.state.scene)||row.state.chapter!==1){$('saves-message').textContent='此存档版本暂不支持。';return;}if(row.state.scene==='play'){characterName=row.state.character_name||characterName;beginStory(true);}else{show('room');$('case-note').textContent='已读取存档 '+slot+'，回到第'+row.state.chapter+'章的身份线索。';}});actions.append(write,read);box.append(title,text,time,actions);list.append(box);}}
async function refreshSaves(report){const owner=currentName;try{const data=await request('saves');if(owner!==currentName)return;saveRows=data.saves;$('save-note').textContent=saveRows.length?'已有 '+saveRows.length+' 份存档':'暂无存档';renderSaves();if(report)$('saves-message').textContent=saveRows.length?'已读取这个账号的存档。':'暂无存档，可以保存当前调查进度。';}catch(error){if(owner!==currentName)return;$('save-note').textContent='点击查看存档';if(report)$('saves-message').textContent=error.message;}}
async function saveSlot(slot){const buttons=$('save-list').querySelectorAll('button');buttons.forEach(x=>x.disabled=true);$('saves-message').textContent='正在保存…';try{const data=await request('save',{slot});saveRows=data.saves;renderSaves();$('save-note').textContent='已有 '+saveRows.length+' 份存档';$('saves-message').textContent='存档已保存到你的账号。';}catch(error){renderSaves();$('saves-message').textContent=error.message;}}
$('archive').addEventListener('click',()=>{if(!currentName){afterLogin='saves';setMode('login');show('auth');$('name').focus({preventScroll:true});return;}show('saves');$('saves-message').textContent='正在读取…';refreshSaves(true);});
$('saves-back').addEventListener('click',()=>show('room'));

$('board-start').addEventListener('click',()=>{if(!currentName){afterLogin='play';setMode('login');show('auth');$('form-message').textContent='请先登录，角色名字和进度会跟随你的账号。';return;}beginStory();});

async function restoreProfile(){const owner=currentName;try{const data=await request('profile');if(owner!==currentName)return;characterName=data.character_name;renderSaves();}catch(error){if(!$('play').hidden)$('character-message').textContent=error.message;}}
function renderDialogue(){$('story-line').textContent=characterName?'你好，'+characterName+'。':'你好同学，你叫什么名字：';$('character-form').hidden=!!characterName;$('story-back').hidden=!characterName;$('character-message').textContent=characterName?'你的名字已跟随账号保存。':'';}
function beginStory(skipHint=false){if(introTimer)clearTimeout(introTimer);musicEnabled=false;bgm.pause();bgm.currentTime=0;show('play');$('orientation-note').classList.remove('fading');$('orientation-note').hidden=skipHint;$('story-dialogue').hidden=!skipHint;renderDialogue();restoreProfile().then(()=>{if(!$('story-dialogue').hidden)renderDialogue();});if(!skipHint)introTimer=setTimeout(()=>{$('orientation-note').classList.add('fading');introTimer=setTimeout(()=>{$('orientation-note').hidden=true;$('story-dialogue').hidden=false;renderDialogue();},1500);},5000);}
$('character-form').addEventListener('submit',async event=>{event.preventDefault();$('character-submit').disabled=true;$('character-message').textContent='正在记录你的名字…';try{const data=await request('profile',{name:$('character-name').value.trim()});characterName=data.character_name;renderDialogue();renderSaves();}catch(error){$('character-message').textContent=error.message;}finally{$('character-submit').disabled=false;}});
$('story-back').addEventListener('click',()=>{if(introTimer)clearTimeout(introTimer);show('room');$('case-note').textContent=characterName?'调查员 '+characterName+'，可在存档卡片保存当前进度。':'第一条线索：确认你的身份。';});
